
// 文化祭モザイクアート「結」 データ
// このファイルを data/others/mosaic_data.js に保存してください。
(function () {
  const encoded = "";
  const binary = atob(encoded);
  const values = [];
  for (let i = 0; i < binary.length; i++) {
    const byte = binary.charCodeAt(i);
    values.push((byte >> 4) & 15, byte & 15);
  }
  values.length = 3968;
  const grid = [];
  for (let y = 0; y < 62; y++) {
    grid.push(values.slice(y * 64, (y + 1) * 64));
  }
  window.MOSAIC_DATA = {
    title: "結 ― 星降る文化祭 ―",
    width: 64, height: 62, cell_count: 3968,
    palette: {
      "0": {"hex":"#002073","name":"濃紺"},
      "1": {"hex":"#9C55FF","name":"紫"},
      "2": {"hex":"#3130AD","name":"青紫"},
      "3": {"hex":"#BDBAFF","name":"薄紫"},
      "4": {"hex":"#FFCF63","name":"金色"},
      "5": {"hex":"#FFEFDE","name":"アイボリー"},
      "6": {"hex":"#522031","name":"暗赤"},
      "7": {"hex":"#73CFFF","name":"水色"},
      "8": {"hex":"#9C659C","name":"藤色"},
      "9": {"hex":"#BD6542","name":"茶橙"},
      "10": {"hex":"#008ABD","name":"青"},
      "11": {"hex":"#FF65AD","name":"ピンク"},
      "12": {"hex":"#DE20BD","name":"濃いピンク"},
      "13": {"hex":"#FF0063","name":"赤ピンク"},
      "14": {"hex":"#8C0063","name":"濃紫"}
    },
    grid: grid
  };
})();
